function db():PDO{static $p=null;if(!$p)$p=new PDO('mysql:host='.DB_HOST.';dbname='.DB_NAME.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);return $p;}
function out($d,int $s=200):never{http_response_code($s);header('Content-Type: application/json; charset=utf-8');echo json_encode($d,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function body():array{$v=json_decode(file_get_contents('php://input'),true);return is_array($v)?$v:[];}
function bad(string $m,int $s=400):never{out(['detail'=>$m],$s);}
function auth($p):void{if(ADMIN_PASSWORD===''||!is_string($p)||!hash_equals(ADMIN_PASSWORD,$p))bad('Unauthorized',403);}
function tok(int $n=8):string{$c='abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';$v='';for($i=0;$i<$n;$i++)$v.=$c[random_int(0,61)];return $v;}
function ip():string{return $_SERVER['REMOTE_ADDR']??'0.0.0.0';}
function validurl(string $u):bool{$p=parse_url($u);return is_array($p)&&in_array(strtolower($p['scheme']??''),['http','https'],true)&&!empty($p['host']);}
function bot():array{$ua=$_SERVER['HTTP_USER_AGENT']??'';$u=strtolower($ua);$patterns=['bot','crawl','spider','slurp','googlebot','bingbot','python-requests','curl','wget','scrapy','selenium','puppeteer','playwright','httpx','requests','urllib','semrush','facebookexternalhit','twitterbot','whatsapp','telegram','discordbot','lighthouse','uptimerobot'];if($ua===''||strlen($ua)<20)return [true,'Missing or short User-Agent'];foreach($patterns as $x)if(str_contains($u,$x))return [true,'UA pattern: '.$x];if(!str_starts_with($ua,'Mozilla/')||empty($_SERVER['HTTP_ACCEPT'])||empty($_SERVER['HTTP_ACCEPT_LANGUAGE']))return [true,'Incomplete browser headers'];return [false,''];}
function dev(string $ua):array{$u=strtolower($ua);$d=preg_match('/iphone|android|mobile|blackberry/',$u)?'Mobile':(preg_match('/ipad|tablet/',$u)?'Tablet':'Desktop');$b=str_contains($u,'chrome')&&!str_contains($u,'edg')?'Chrome':(str_contains($u,'firefox')?'Firefox':(str_contains($u,'safari')&&!str_contains($u,'chrome')?'Safari':(str_contains($u,'edg')?'Edge':'Other')));$o=str_contains($u,'windows')?'Windows':(str_contains($u,'android')?'Android':(str_contains($u,'iphone')||str_contains($u,'ipad')?'iOS':(str_contains($u,'linux')?'Linux':'Other')));return ['device'=>$d,'browser'=>$b,'os'=>$o];}
function logvisit(string $t,string $status,string $reason=''):void{$ua=$_SERVER['HTTP_USER_AGENT']??'';$d=dev($ua);$q=db()->prepare('INSERT INTO visits(token,ip,ua,device,browser,os,referer,status,reason,ts) VALUES(?,?,?,?,?,?,?,?,?,UTC_TIMESTAMP())');$q->execute([$t,ip(),$ua,$d['device'],$d['browser'],$d['os'],$_SERVER['HTTP_REFERER']??'',$status,$reason]);$col=['success'=>'visits','blocked'=>'blocked','bot'=>'bots','captcha_fail'=>'captcha_fails','captcha_pending'=>'clicks'][$status]??null;if($col)foreach(['urls','redirects'] as $tb){$q=db()->prepare("UPDATE $tb SET $col=$col+1,last_visit=UTC_TIMESTAMP() WHERE token=?");$q->execute([$t]);}}
function verifyhtml(string $t,string $endpoint):never{$k=htmlspecialchars(HCAPTCHA_SITEKEY,ENT_QUOTES);$t=htmlspecialchars($t,ENT_QUOTES);$e=htmlspecialchars($endpoint,ENT_QUOTES);header('Content-Type:text/html;charset=utf-8');echo '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verify - Anti Bypass</title><script src="https://js.hcaptcha.com/1/api.js" async defer></script><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#080b14;color:#edf3ff;font:15px system-ui}.card{width:min(390px,calc(100% - 40px));padding:28px;border:1px solid #26334b;border-radius:18px;background:#101827;text-align:center}button{width:100%;padding:13px;margin-top:20px;border:0;border-radius:10px;background:#09b9d5;font-weight:700}button:disabled{opacity:.4}</style></head><body><main class="card"><h2>Anti Bypass</h2><h1>Verify Access</h1><p>Complete CAPTCHA to continue.</p><div class="h-captcha" data-sitekey="'.$k.'" data-callback="solved"></div><button id="go" disabled onclick="verifyNow()">Continue</button><p id="msg"></p></main><script>let cap="";function solved(v){cap=v;document.getElementById("go").disabled=false}async function verifyNow(){let b=document.getElementById("go");b.disabled=true;b.textContent="Verifying...";try{let r=await fetch("'.$e.'",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({cap:cap,t:"'.$t.'"})});let d=await r.json();if(!r.ok||!d.ok)throw Error(d.detail||"Verification failed");location.href=d.redirect||("/p?s="+encodeURIComponent(d.sid))}catch(x){document.getElementById("msg").textContent=x.message;b.disabled=false;b.textContent="Try Again"}}</script></body></html>';exit;}
function captcha(string $v):bool{if(HCAPTCHA_SECRET==='')return false;$c=curl_init('https://api.hcaptcha.com/siteverify');curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query(['secret'=>HCAPTCHA_SECRET,'response'=>$v,'remoteip'=>ip()]),CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>12]);$r=curl_exec($c);curl_close($c);$d=json_decode((string)$r,true);return is_array($d)&&!empty($d['success']);}
function setting(string $k):?array{$q=db()->prepare('SELECT value_json FROM settings WHERE setting_key=?');$q->execute([$k]);$v=$q->fetchColumn();return $v?json_decode($v,true):null;}
function setsetting(string $k,array $v):void{$q=db()->prepare('INSERT INTO settings(setting_key,value_json) VALUES(?,?) ON DUPLICATE KEY UPDATE value_json=VALUES(value_json)');$q->execute([$k,json_encode($v)]);}
function applyshort(string $url):string{$c=setting('shortener');if(!$c||empty($c['enabled'])||empty($c['shortener_url'])||empty($c['shortener_api_key']))return $url;$ch=curl_init(rtrim($c['shortener_url'],'/').'?'.http_build_query(['api'=>$c['shortener_api_key'],'url'=>$url,'format'=>'json']));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>10]);$r=curl_exec($ch);$err=curl_error($ch);curl_close($ch);if($r===false)bad('Shortener API failed: '.$err,502);$d=json_decode($r,true);if(!is_array($d)||($d['status']??'')!=='success'||empty($d['shortenedUrl']))bad('Shortener returned an error.',400);return $d['shortenedUrl'];}
