if($path==='/api/verify'&&$method==='POST'){$b=body();$t=(string)($b['t']??'');if(empty($b['cap'])||strlen($t)!==62)bad('Missing fields');if(!captcha((string)$b['cap'])){logvisit($t,'captcha_fail','hCaptcha failed');out(['ok'=>false,'detail'=>'Captcha verification failed.'],403);}$q=db()->prepare('SELECT target_url,active FROM urls WHERE token=?');$q->execute([$t]);$d=$q->fetch();if(!$d||!$d['active'])out(['ok'=>false,'detail'=>'Token not found or disabled.'],404);$sid=bin2hex(random_bytes(40));$q=db()->prepare('INSERT INTO sessions(sid,token,target,expires,ip) VALUES(?,?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 2 HOUR),?)');$q->execute([$sid,$t,$d['target_url'],ip()]);logvisit($t,'success');out(['ok'=>true,'sid'=>$sid]);}
if($path==='/p'&&$method==='GET'){$sid=(string)($_GET['s']??'');$q=db()->prepare('SELECT * FROM sessions WHERE sid=?');$q->execute([$sid]);$s=$q->fetch();if(!$s||strtotime($s['expires'])<time()||$s['used'])bad('Session expired or already used',403);$q=db()->prepare('UPDATE sessions SET used=1 WHERE sid=? AND used=0');$q->execute([$sid]);if(!$q->rowCount())bad('Session already used',403);header('Location:'.$s['target'],true,302);exit;}
if((preg_match('#^/r/([A-Za-z0-9]+)$#',$path,$m)||$path==='/go')&&$method==='GET'){$t=$m[1]??(string)($_GET['t']??'');if(!in_array(strlen($t),[8,32],true))bad('Invalid token',404);$q=db()->prepare('SELECT * FROM redirects WHERE token=?');$q->execute([$t]);$d=$q->fetch();if(!$d)bad('Link not found',404);if($d['expires']&&strtotime($d['expires'])<time())bad('Link expired',410);[$b,$why]=bot();if($b){logvisit($t,'bot',$why);bad('Access denied',403);}$q=db()->prepare('SELECT id FROM blocked_ips WHERE ip=?');$q->execute([ip()]);if($q->fetch()){logvisit($t,'blocked','IP blocklist');bad('Access denied',403);}logvisit($t,'captcha_pending');verifyhtml($t,'/api/go-verify');}
if($path==='/api/go-verify'&&$method==='POST'){$b=body();$t=(string)($b['t']??'');if(empty($b['cap'])||!in_array(strlen($t),[8,32],true))bad('Missing fields');if(!captcha((string)$b['cap'])){logvisit($t,'captcha_fail','hCaptcha failed');out(['ok'=>false,'detail'=>'Captcha failed.'],403);}$q=db()->prepare('SELECT url,expires FROM redirects WHERE token=?');$q->execute([$t]);$d=$q->fetch();if(!$d)out(['ok'=>false,'detail'=>'Token not found.'],404);if($d['expires']&&strtotime($d['expires'])<time())out(['ok'=>false,'detail'=>'Link expired.'],410);logvisit($t,'success');out(['ok'=>true,'redirect'=>$d['url']]);}
if($path==='/api'&&$method==='GET'){$url=(string)($_GET['url']??'');$api=(string)($_GET['api']??'');$expiry=trim((string)($_GET['expiry']??''));[$b]=bot();if($b)out(['status'=>'error','message'=>['Access denied — bot detected.'],'shortenedUrl'=>''],403);if(!validurl($url))out(['status'=>'error','message'=>['URL is invalid.'],'shortenedUrl'=>''],400);$h=null;$label='permanent';if($expiry!==''&&!in_array(strtolower($expiry),['0','∞','permanent','forever','inf','infinity'],true)){if(!ctype_digit($expiry)||(int)$expiry<1)out(['status'=>'error','message'=>['Invalid expiry value.'],'shortenedUrl'=>''],400);$h=(int)$expiry;$label=$h.'h';}if($api!==''){$q=db()->prepare('SELECT id FROM api_keys WHERE api_key=? AND active=1');$q->execute([$api]);if(!$q->fetch())out(['status'=>'error','message'=>['Invalid or inactive API key.'],'shortenedUrl'=>''],401);$q=db()->prepare('UPDATE api_keys SET usage_count=usage_count+1,last_used=UTC_TIMESTAMP() WHERE api_key=?');$q->execute([$api]);}$url=applyshort($url);$t=tok();$q=db()->prepare('SELECT id FROM redirects WHERE token=?');$q->execute([$t]);while($q->fetch()){$t=tok();$q->execute([$t]);}$exp=$h?'DATE_ADD(UTC_TIMESTAMP(),INTERVAL '.(int)$h.' HOUR)':'NULL';$q=db()->prepare('INSERT INTO redirects(token,url,api_key,created,expires,permanent,source) VALUES(?,?,?,UTC_TIMESTAMP(),'.$exp.',?,"api")');$q->execute([$t,$url,$api?:null,$h?0:1]);out(['status'=>'success','message'=>'','shortenedUrl'=>BASE_URL.'/r/'.$t,'expiry'=>$label]);}
if(str_starts_with($path,'/admin/')){$b=body();auth($method==='GET'?($_GET['password']??''):($b['password']??null));
if($path==='/admin/add-url'&&$method==='POST'){$url=(string)($b['target_url']??'');if(!validurl($url))bad('Invalid target URL');$url=applyshort($url);$t=tok();$h=(int)($b['expiry_hours']??0);$exp=$h>0?'DATE_ADD(UTC_TIMESTAMP(),INTERVAL '.$h.' HOUR)':'NULL';$q=db()->prepare('INSERT INTO redirects(token,url,label,source,permanent,expires,created) VALUES(?,?,?,"admin",?,'.$exp.',UTC_TIMESTAMP())');$q->execute([$t,$url,(string)($b['label']??''),$h>0?0:1]);out(['ok'=>true,'token'=>$t,'url'=>BASE_URL.'/r/'.$t,'expiry'=>$h>0?$h.'h':'permanent']);}
if($path==='/admin/delete-url'&&$method==='POST'){$t=(string)($b['token']??'');$q=db()->prepare('DELETE FROM redirects WHERE token=?');$q->execute([$t]);if(!$q->rowCount()){$q=db()->prepare('DELETE FROM urls WHERE token=?');$q->execute([$t]);if(!$q->rowCount())bad('Not found',404);foreach(['visits','sessions'] as $tb){$q=db()->prepare("DELETE FROM $tb WHERE token=?");$q->execute([$t]);}}out(['ok'=>true]);}
if($path==='/admin/go-links'&&$method==='GET'){$rows=db()->query("SELECT * FROM redirects WHERE source='admin' ORDER BY created DESC LIMIT 200")->fetchAll();foreach($rows as &$r)$r['short_url']=BASE_URL.'/r/'.$r['token'];out($rows);}
if($path==='/admin/toggle-url'&&$method==='POST'){$q=db()->prepare('UPDATE urls SET active=? WHERE token=?');$q->execute([!empty($b['active'])?1:0,(string)($b['token']??'')]);out(['ok'=>true]);}
if($path==='/admin/block-ip'&&$method==='POST'){$q=db()->prepare('INSERT INTO blocked_ips(ip,reason,ts) VALUES(?,?,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE reason=VALUES(reason),ts=VALUES(ts)');$q->execute([(string)($b['ip']??''),(string)($b['reason']??'')]);out(['ok'=>true]);}
if($path==='/admin/unblock-ip'&&$method==='POST'){$q=db()->prepare('DELETE FROM blocked_ips WHERE ip=?');$q->execute([(string)($b['ip']??'')]);out(['ok'=>true]);}
if($path==='/admin/urls'&&$method==='GET'){$rows=db()->query('SELECT * FROM urls ORDER BY created DESC LIMIT 500')->fetchAll();foreach($rows as &$r)$r['short_url']=BASE_URL.'/token?t='.$r['token'];out($rows);}
if($path==='/admin/url-details'&&$method==='GET'){$t=(string)($_GET['token']??'');$q=db()->prepare('SELECT * FROM urls WHERE token=?');$q->execute([$t]);$d=$q->fetch();if(!$d)bad('Not found',404);$d['short_url']=BASE_URL.'/token?t='.$t;$d['stats']=['clicks'=>(int)$d['clicks'],'visits'=>(int)$d['visits'],'bots'=>(int)$d['bots'],'blocked'=>(int)$d['blocked'],'captcha_fails'=>(int)$d['captcha_fails']];$q=db()->prepare('SELECT * FROM visits WHERE token=? ORDER BY ts DESC LIMIT 200');$q->execute([$t]);out(['url'=>$d,'visits'=>$q->fetchAll()]);}
if($path==='/admin/visits'&&$method==='GET'){$n=max(1,min(500,(int)($_GET['limit']??100)));$t=(string)($_GET['token']??'');$q=$t!==''?db()->prepare('SELECT * FROM visits WHERE token=? ORDER BY ts DESC LIMIT '.$n):db()->query('SELECT * FROM visits ORDER BY ts DESC LIMIT '.$n);if($t!=='')$q->execute([$t]);out($q->fetchAll());}
