if($path==='/admin/stats'&&$method==='GET'){$s=['total_urls'=>(int)db()->query('SELECT (SELECT COUNT(*) FROM urls)+(SELECT COUNT(*) FROM redirects)')->fetchColumn()];foreach(['clicks'=>'total_clicks','visits'=>'total_visits','blocked'=>'total_blocked','bots'=>'total_bots','captcha_fails'=>'total_captcha_fails'] as $c=>$k)$s[$k]=(int)db()->query("SELECT (SELECT COALESCE(SUM($c),0) FROM urls)+(SELECT COALESCE(SUM($c),0) FROM redirects)")->fetchColumn();$agg=fn($c)=>db()->query("SELECT COALESCE($c,'Unknown') AS _id,COUNT(*) AS count FROM visits GROUP BY $c ORDER BY count DESC LIMIT 10")->fetchAll();out(['summary'=>$s,'timeline'=>db()->query("SELECT DATE_FORMAT(ts,'%Y-%m-%d') AS _id,COUNT(*) AS count FROM visits WHERE ts>=UTC_TIMESTAMP()-INTERVAL 7 DAY GROUP BY DATE(ts) ORDER BY DATE(ts)")->fetchAll(),'hourly'=>db()->query("SELECT HOUR(ts) AS _id,COUNT(*) AS count FROM visits WHERE ts>=UTC_DATE() AND status='success' GROUP BY HOUR(ts) ORDER BY HOUR(ts)")->fetchAll(),'devices'=>$agg('device'),'browsers'=>$agg('browser'),'statuses'=>$agg('status'),'top_ips'=>db()->query('SELECT ip AS _id,COUNT(*) AS count FROM visits GROUP BY ip ORDER BY count DESC LIMIT 10')->fetchAll(),'blocked_ips'=>db()->query('SELECT * FROM blocked_ips ORDER BY ts DESC LIMIT 100')->fetchAll(),'recent_bots'=>db()->query("SELECT * FROM visits WHERE status='bot' ORDER BY ts DESC LIMIT 20")->fetchAll(),'bot_reasons'=>db()->query("SELECT reason AS _id,COUNT(*) AS count FROM visits WHERE status='bot' GROUP BY reason ORDER BY count DESC LIMIT 10")->fetchAll()]);}
